contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        bool alreadyInitialized = c.initialized();
        require(!alreadyInitialized, "pool must be fresh");

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool highFee = _feeRate > 5000;
        address baseTokenAfter = c.baseToken();
        bool initializedAfter = c.initialized();

        assert(
            (highFee && reverted && !initializedAfter) ||
            (!highFee && !reverted && initializedAfter && baseTokenAfter == _baseToken)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address a,
        address n,
        uint128 vB,
        uint128 vN,
        uint56 cf,
        uint16 fr,
        bytes32 mr,
        bool usno,
        bool pr
    ) public payable {
        require(fr <= 5000);

        bool firstOk;
        try c.initialize(a, n, vB, vN, cf, fr, mr, usno, pr) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        address afterFirst = c.nft();

        bool secondOk;
        try c.initialize(a, n, vB, vN, cf, fr, mr, usno, pr) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        address afterSecond = c.nft();

        assert(
            (firstOk && afterFirst == n && afterSecond == n && !secondOk) ||
            (!firstOk && afterFirst == address(0) && afterSecond == address(0))
        );
    }

    receive() external payable {}
}

